-- Create "am_units" table
CREATE TABLE "core"."am_units" (
  "am_unit_id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "next_unit_id" integer NULL,
  "previous_unit_id" integer NULL,
  "active_measurement_id" integer NOT NULL DEFAULT 0,
  "reviewed_area_id" integer NOT NULL DEFAULT 0,
  "reg_model_id" integer NOT NULL DEFAULT 0,
  "dect_model_id" integer NOT NULL DEFAULT 0,
  "created_by_user_id" integer NOT NULL DEFAULT 0,
  "model_count" double precision NULL,
  "human_count" integer NULL,
  "current_count" double precision NULL,
  "current_ci_lower" double precision NULL,
  "current_ci_upper" double precision NULL,
  "created" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "modified" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "uuid" uuid NOT NULL DEFAULT gen_random_uuid(),
  PRIMARY KEY ("am_unit_id"),
  CONSTRAINT "am_units_dect_model_id_key" UNIQUE ("dect_model_id"),
  CONSTRAINT "am_units_next_unit_id_key" UNIQUE ("next_unit_id"),
  CONSTRAINT "am_units_previous_unit_id_key" UNIQUE ("previous_unit_id"),
  CONSTRAINT "am_units_reg_model_id_key" UNIQUE ("reg_model_id"),
  CONSTRAINT "am_units_uuid_key" UNIQUE ("uuid"),
  CONSTRAINT "am_units_active_measurement_id_fkey" FOREIGN KEY ("active_measurement_id") REFERENCES "projectmanagement"."active_measurements" ("active_measurement_id") ON UPDATE CASCADE ON DELETE CASCADE DEFERRABLE,
  CONSTRAINT "am_units_am_unit_id_fkey" FOREIGN KEY ("am_unit_id") REFERENCES "core"."am_units" ("previous_unit_id") ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE,
  CONSTRAINT "am_units_am_unit_id_fkey1" FOREIGN KEY ("am_unit_id") REFERENCES "core"."am_units" ("next_unit_id") ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE,
  CONSTRAINT "am_units_created_by_user_id_fkey" FOREIGN KEY ("created_by_user_id") REFERENCES "usermanagement"."users" ("user_id") ON UPDATE CASCADE ON DELETE SET DEFAULT DEFERRABLE,
  CONSTRAINT "am_units_reviewed_area_id_fkey" FOREIGN KEY ("reviewed_area_id") REFERENCES "core"."reviewed_area" ("reviewed_area_id") ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE
);
